import{_ as a}from"./chunks/single-publish.dkGMB9e8.js";import{_ as r,c as e,o as l,ag as i}from"./chunks/framework._xRlcm3f.js";const g=JSON.parse('{"title":"详细发布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/single-publish.md","filePath":"guide/single-publish.md","lastUpdated":1791882408000}'),d={name:"guide/single-publish.md"};function o(s,t,n,h,c,u){return l(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="详细发布" tabindex="-1">详细发布 <a class="header-anchor" href="#详细发布" aria-label="Permalink to &quot;详细发布&quot;">​</a></h1><p>详细发布把发布前的每一项参数都摊开：标题、摘要、标签、分类、别名、发布时间、状态等，适合需要精细控制的场景。</p><p><img src="'+a+'" alt="详细发布：选择平台" loading="lazy"></p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><ul><li>快速发布的平台卡片上点「详细发布」</li><li>文章管理里某篇文档的「单发」</li></ul><h2 id="两步流程" tabindex="-1">两步流程 <a class="header-anchor" href="#两步流程" aria-label="Permalink to &quot;两步流程&quot;">​</a></h2><h3 id="第一步-选择平台" tabindex="-1">第一步：选择平台 <a class="header-anchor" href="#第一步-选择平台" aria-label="Permalink to &quot;第一步：选择平台&quot;">​</a></h3><p>按平台图标选择目标平台。已发布过的平台会标出「预览」，未发布的标「未发布」。</p><h3 id="第二步-编辑发布内容" tabindex="-1">第二步：编辑发布内容 <a class="header-anchor" href="#第二步-编辑发布内容" aria-label="Permalink to &quot;第二步：编辑发布内容&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>编辑模式</td><td>简洁 / 详细 / 源码三种，按需要切换</td></tr><tr><td>文章标题</td><td>默认取文档标题，可修改，也可点「自动提取标题」</td></tr><tr><td>摘要</td><td>平台未返回时回退到思源笔记的摘要</td></tr><tr><td>标签 / 分类</td><td>平台支持时生效；平台未返回时回退到思源笔记</td></tr><tr><td>知识空间 / 专栏 / 文集</td><td>取决于平台；配置存值，编辑时只读</td></tr><tr><td>别名（slug）</td><td>影响文章链接；文档没生成过时按本次发布结果写回</td></tr><tr><td>图床服务</td><td>按平台分别指定</td></tr><tr><td>同步修改到思源笔记</td><td>勾选后把本次改动写回文档</td></tr></tbody></table><h3 id="源码模式与图片" tabindex="-1">源码模式与图片 <a class="header-anchor" href="#源码模式与图片" aria-label="Permalink to &quot;源码模式与图片&quot;">​</a></h3><p>源码模式显示文档的<strong>原始 Markdown</strong>（图片为本地 <code>assets/</code> 路径），编辑期间不改动文档：</p><ul><li>图片的<strong>上传与链接替换统一在发布时执行</strong>——发布后平台侧拿到的是图床（或平台）地址</li><li>正文包含图片时，编辑区顶部会给出提示，并可点「<strong>上传并预览替换后的内容</strong>」：立即上传图片并以替换后的结果预览，再点「恢复原文」切回</li><li>预览<strong>仅用于查看</strong>，不写入文档；保存与发布始终使用原始内容</li><li>预览适用于「PicGo」与平台自带图床（配置里的「当前平台」）两种方式；图床服务选「不使用」时不提示；批量分发没有单平台上下文，不提供预览</li></ul><h2 id="可以做的操作" tabindex="-1">可以做的操作 <a class="header-anchor" href="#可以做的操作" aria-label="Permalink to &quot;可以做的操作&quot;">​</a></h2><ul><li><strong>发布 / 更新</strong>：首次发布用「发布」，之后用「更新」</li><li><strong>强制删除</strong>：清理该平台的发布记录</li><li><strong>查看文章</strong>：按「预览规则」模板拼出链接并打开</li></ul><div class="tip custom-block"><p class="custom-block-title">合并模式的例外</p><p>批量分发使用「合并」模式时，标题与摘要的改动不生效（标签与分类会合并）。需要改标题请回到单平台发布操作。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>一次发到多个平台：<a href="./batch-publish.html">批量分发</a></li><li>回看发布记录：<a href="./article-manage.html">文章管理</a></li></ul>',18)])])}const m=r(d,[["render",o]]);export{g as __pageData,m as default};
